            if (speed.hasModifier(attributemodifier)) {
                speed.removeModifier(attributemodifier);
                speed.addPermanentModifier(attributemodifier);
            } else {
                speed.addPermanentModifier(attributemodifier);
            }
        } else {
            speed.removePermanentModifier(SPEED_BOOST_AQUATIC_LAND_UUID);
        }
    }
}

